from collections import deque
class Solution:
    def minimumObstacles(self, grid) -> int:
        n=len(grid)
        m=len(grid[0])



        q=deque()
        q.append((0,0))

        d=[[-1]*m for _ in range(n)]
        d[0][0]=m+n-1
        while q:
            x,y=q.popleft()

            for nx, ny in [(x-1,y),(x+1,y),(x,y-1),(x,y+1)]:
                if 0<=nx<n and 0<=ny<m:
                    if d[x][y]-grid[nx][ny]<=d[nx][ny]:
                        continue

                    q.append((nx,ny))
                    d[nx][ny]=d[x][y]-grid[nx][ny]
                    if (nx,ny)==(n-1,m-1):
                        break






        return m+n-1-d[n-1][m-1]

